int RunTrayProbe(const fs::path& directory){
    if(fs::exists(directory/L"settings.json")||fs::exists(directory/L"shell-original.json"))return 2;
    Application app(directory,true);app.monitors=GetMonitors();if(app.monitors.empty())return 2;TrayProbe probe{app};probe.Run();json::JsonObject report;report.SetNamedValue(L"passed",json::JsonValue::CreateBooleanValue(probe.passed));report.SetNamedValue(L"checks",probe.checks);if(!WriteAtomic(directory/L"tray-smoke.json",std::wstring(report.Stringify())))return 2;return probe.passed?0:1;
}
